/* OpenIC-assets-7.js - part 7 of 7 of the game icons for Open IC Creator's in-game window: icon sheets as data: URIs. OpenIC.iss loads the parts into the window's page
   (ISXOgreX.UI:EvalFile) one at a time once the window is open. Built by tools/build-window.js. The icons are
   EverQuest II's own art (Daybreak Game Company). */
(function () {
  var L = window.OpenIC_LIB;
  if (!L || !L.IC) return;
  var st = document.getElementById('openic-icon-sheets-7');
  if (!st) { st = document.createElement('style'); st.id = 'openic-icon-sheets-7'; (document.head || document.body).appendChild(st); }
  st.textContent = ".oic-it-3{background-image:url(data:image/png;base64,);}\n.oic-it-4{background-image:url(data:image/png;base64,);}\n";
  if (L.IC.app && L.IC.app.iconsLoaded) L.IC.app.iconsLoaded();
  if (typeof window.ogreUISet === 'function') window.ogreUISet('openic', 'openic-assets-got', '7/7');
})();
